import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64

.visible .entry matvec_mul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .u32 %r<50>;
    .reg .u64 %rd<60>;
    .reg .f32 %f<30>;
    .reg .pred %p<8>;

    .shared .align 4 .b8 sdata[1024];

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [K];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %ntid.x;

    setp.ge.u32 %p1, %r3, %r1;
    @%p1 bra DONE;

    cvt.u64.u32 %rd4, %r3;
    cvt.u64.u32 %rd5, %r2;
    mul.lo.u64 %rd6, %rd4, %rd5;

    mov.f32 %f1, 0f00000000;
    shr.u32 %r30, %r2, 2;
    shl.b32 %r31, %r30, 2;
    mov.u32 %r40, %r4;
VLOOP_START:
    setp.ge.u32 %p2, %r40, %r30;
    @%p2 bra VLOOP_END;
    cvt.u64.u32 %rd30, %r40;
    shl.b64 %rd31, %rd30, 2;
    add.u64 %rd32, %rd6, %rd31;
    shl.b64 %rd33, %rd32, 2;
    add.u64 %rd34, %rd1, %rd33;
    ld.global.v4.f32 {%f10, %f11, %f12, %f13}, [%rd34];
    shl.b64 %rd35, %rd31, 2;
    add.u64 %rd36, %rd2, %rd35;
    ld.global.v4.f32 {%f20, %f21, %f22, %f23}, [%rd36];
    fma.rn.f32 %f1, %f10, %f20, %f1;
    fma.rn.f32 %f1, %f11, %f21, %f1;
    fma.rn.f32 %f1, %f12, %f22, %f1;
    fma.rn.f32 %f1, %f13, %f23, %f1;
    add.u32 %r40, %r40, %r5;
    bra VLOOP_START;
VLOOP_END:
    add.u32 %r41, %r31, %r4;
    cvt.u64.u32 %rd7, %r41;
TLOOP_START:
    setp.ge.u64 %p6, %rd7, %rd5;
    @%p6 bra TLOOP_END;
    add.u64 %rd9, %rd6, %rd7;
    shl.b64 %rd10, %rd9, 2;
    add.u64 %rd11, %rd1, %rd10;
    ld.global.f32 %f2, [%rd11];
    shl.b64 %rd12, %rd7, 2;
    add.u64 %rd13, %rd2, %rd12;
    ld.global.f32 %f3, [%rd13];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    cvt.u64.u32 %rd14, %r5;
    add.u64 %rd7, %rd7, %rd14;
    bra TLOOP_START;
TLOOP_END:
    mov.u32 %r10, sdata;
    mad.lo.u32 %r11, %r4, 4, %r10;
    st.shared.f32 [%r11], %f1;

    bar.sync 0;

    mov.u32 %r20, 128;

RED_LOOP:
    setp.eq.u32 %p4, %r20, 0;
    @%p4 bra RED_DONE;

    setp.ge.u32 %p3, %r4, %r20;
    @%p3 bra RED_CONT;

    add.u32 %r23, %r4, %r20;
    mad.lo.u32 %r24, %r4, 4, %r10;
    mad.lo.u32 %r25, %r23, 4, %r10;
    ld.shared.f32 %f4, [%r24];
    ld.shared.f32 %f5, [%r25];
    add.f32 %f4, %f4, %f5;
    st.shared.f32 [%r24], %f4;

RED_CONT:
    bar.sync 0;
    shr.u32 %r20, %r20, 1;
    bra RED_LOOP;

RED_DONE:
    setp.ne.u32 %p5, %r4, 0;
    @%p5 bra DONE;

    ld.shared.f32 %f6, [%r10];

    cvt.u64.u32 %rd20, %r3;
    shl.b64 %rd21, %rd20, 2;
    add.u64 %rd22, %rd3, %rd21;
