        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32

        A_c = A.contiguous()
        B_c = B.contiguous()

        M, K = A_c.shape
        assert B_c.shape[0] == K

        C = torch.empty((M, 1), device=A_c.device, dtype=A_c.dtype)

        module = _get_ptx_module()

        block = (256, 1, 1)
        grid = (M, 1, 1)

        module.launch(
            "matvec_mul",
            grid=grid,
            block=block,
            arguments=[A_c, B_c, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A_c.device),
        )

        return C

